mapper.select:
SELECT MEMBER_NO
FROM GROUP_CHAT_MEMBER
WHERE GROUP_ROOM_NO = #{groupRoomNo}

SELECT * FROM ( SELECT gm.GROUP_MSG_NO, gm.GROUP_ROOM_NO, gm.SENDER_NO, m.NICKNAME AS SENDER_NICKNAME, m.PROFILE_IMAGE AS SENDER_PROFILE, gm.MSG_CONTENT, TO_CHAR(gm.SEND_TIME, 'YYYY-MM-DD HH24:MI') AS SEND_TIME, 1 AS IS_GROUP_MESSAGE FROM GROUP_MESSAGE gm JOIN MEMBER m ON gm.SENDER_NO = m.MEMBER_NO WHERE gm.GROUP_ROOM_NO = #{groupRoomNo}
AND gm.GROUP_MSG_NO < #{beforeMsgNo}
ORDER BY gm.GROUP_MSG_NO DESC FETCH FIRST #{limit} ROWS ONLY ) sub ORDER BY sub.GROUP_MSG_NO ASC
